package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertMarketClient.*;import static org.junit.jupiter.api.Assertions.*;
import com.aistock.scheduler.task.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;
@Tag("mysql") class AlertScanPlanMysqlTest {
 AlertScanMysqlTest f;AlertScanPlan plan;Fake market;RevisionClient.Event event;int eventReads;
 @BeforeEach void setup(){f=new AlertScanMysqlTest();f.setup();market=new Fake();RevisionClient revisions=new RevisionClient(){public Event next(long after){eventReads++;return event!=null&&event.eventId()>after?event:null;}public PredictionTaskClient.Page affected(String stock,LocalDate cutoff,String after){throw new AssertionError("Prediction scanner must not be used");}};plan=new AlertScanPlan(f.scans,market,revisions,f.clock,"test",false,20,50,"SH600030,SH600276,SZ000002");}
 RuleRef rule(String id,String stock){return new RuleRef(UUID.fromString(id),UUID.randomUUID(),stock,0,LocalDate.of(2026,10,8));}
 void firstRule(){market.rules=List.of(rule("11111111-1111-1111-1111-111111111111","SH600030"));}
 @Test void staleEventUsesCurrentHeadAndOnlyLatestDueDay(){firstRule();assertTrue(plan.runOnce());var raw=UUID.randomUUID();market.raw=raw;event=new RevisionClient.Event(1,"SH600030",UUID.randomUUID().toString());assertTrue(plan.runOnce());assertEquals(2,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));assertEquals(raw.toString(),f.f.jdbc.queryForObject("select raw_version_id from alert_job where raw_version_id=?",String.class,raw.toString()));assertEquals(1,f.scans.cursor("EVENT",f.clock.instant()).completedEventId());assertEquals(0,f.f.jdbc.queryForObject("select count(*) from alert_job where trade_date<>'2026-10-09'",Integer.class));assertEquals(1,market.refreshes);}
 @Test void rawLagRecordsReasonAndDoesNotQueueOldMarketData(){firstRule();market.published=LocalDate.of(2026,10,8);assertTrue(plan.runOnce());assertEquals(0,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));assertEquals("ALERT_RAW_LAGGING",f.scans.cursor("RECONCILE",f.clock.instant()).lastReason());market.published=LocalDate.of(2026,10,9);f.clock.advance(3600);assertTrue(plan.runOnce());assertEquals(1,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));}
 @Test void refreshFailureCanUseValidCalendarButInvalidSnapshotStopsScan(){firstRule();market.refreshFails=true;assertTrue(plan.runOnce());assertEquals(1,market.refreshes);assertTrue(plan.runOnce());assertEquals(1,market.refreshes);market.calendarInvalid=true;assertFalse(plan.runOnce());assertEquals(1,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));f.clock.advance(300);market.calendarInvalid=false;assertTrue(plan.runOnce());assertEquals(2,market.refreshes);}
 @Test void failedSecondPageResumesAndNewRoundFindsEarlierInsertedRule(){var a=rule("11111111-1111-1111-1111-111111111111","SH600030");var b=rule("22222222-2222-2222-2222-222222222222","SH600030");market.rules=List.of(a,b);market.paginate=true;assertTrue(plan.runOnce());var saved=f.scans.cursor("RECONCILE",f.clock.instant());market.pageFails=true;assertFalse(plan.runOnce());assertEquals(saved.afterId(),f.scans.cursor("RECONCILE",f.clock.instant()).afterId());market.pageFails=false;f.clock.advance(60);assertTrue(plan.runOnce());assertNull(f.scans.cursor("RECONCILE",f.clock.instant()).roundId());market.rules=List.of(rule("00000000-0000-0000-0000-000000000001","SH600030"),a,b);market.paginate=false;f.clock.advance(3600);assertTrue(plan.runOnce());assertEquals(3,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));}
 @Test void aMissingStockDoesNotBlockOtherStocksAndBoundariesAreSharedPerPage(){market.rules=List.of(rule("11111111-1111-1111-1111-111111111111","SH600030"),rule("22222222-2222-2222-2222-222222222222","SH600030"),rule("33333333-3333-3333-3333-333333333333","SH600276"));market.badStock="SH600276";assertTrue(plan.runOnce());assertEquals(2,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));assertEquals(2,market.boundaryReads);assertEquals("ALERT_BOUNDARY_UNAVAILABLE",f.scans.cursor("RECONCILE",f.clock.instant()).lastReason());}
 @Test void crossingCutoffWhileFetchingPageCannotCommitOldRound(){firstRule();market.crossCutoff=true;assertFalse(plan.runOnce());assertEquals(0,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));market.crossCutoff=false;assertTrue(plan.runOnce());assertNull(f.scans.cursor("RECONCILE",f.clock.instant()).roundId());}
 @Test void newRoundCannotBypassUnknownOperation(){firstRule();assertTrue(plan.runOnce());var claim=f.jobs.claim(f.clock.instant());f.jobs.unknown(claim);f.clock.advance(3600);assertTrue(plan.runOnce());assertEquals(1,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));assertEquals(claim.attemptId(),f.jobs.pendingReceipts().get(0).attemptId());}
 @Test void notMetMayBeReevaluatedWithNewRawRevision(){firstRule();assertTrue(plan.runOnce());var c=f.jobs.claim(f.clock.instant());f.jobs.saveEvidence(c,UUID.randomUUID());var eval=f.jobs.claim(f.clock.instant());f.jobs.finish(eval,new AlertJobRecords.Result(eval.attemptId(),"NOT_MET",null,null));market.raw=UUID.randomUUID();event=new RevisionClient.Event(1,"SH600030",UUID.randomUUID().toString());assertTrue(plan.runOnce());assertEquals(2,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("select count(*) from alert_job where state='SUCCEEDED'",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("select count(*) from alert_job where raw_version_id=? and state='QUEUED'",Integer.class,market.raw.toString()));}
 @Test void invalidSavedCalendarRecordsPauseReasonAfterEarlierSuccessfulRefresh(){assertTrue(plan.runOnce());market.calendarInvalid=true;assertFalse(plan.runOnce());assertEquals("CALENDAR_SNAPSHOT_UNVERIFIED",f.f.jdbc.queryForObject("select last_reason from alert_calendar_refresh where id=1",String.class));market.calendarInvalid=false;assertTrue(plan.runOnce());assertNull(f.f.jdbc.queryForObject("select last_reason from alert_calendar_refresh where id=1",String.class));assertEquals(1,market.refreshes);assertEquals(0,f.f.jdbc.queryForObject("select count(*) from alert_job",Integer.class));}
 @Test void disabledTickHasNoExternalCalls(){plan.tick();assertEquals(0,market.refreshes);assertEquals(0,eventReads);}
 class Fake implements AlertMarketClient {
  UUID raw=UUID.randomUUID();LocalDate published=LocalDate.of(2026,10,9);List<RuleRef> rules=List.of();boolean refreshFails,calendarInvalid,pageFails,paginate,crossCutoff;String badStock;int refreshes,boundaryReads;
  public CalendarSnapshot calendar(){var c=AlertCalendarPlanTest.calendar(f.clock.instant());return calendarInvalid?new CalendarSnapshot(c.versionId(),c.provider(),c.start(),c.end(),f.clock.instant().minusSeconds(604801),c.sourcePayloadHash(),c.days()):c;}
  public CalendarSnapshot refresh(UUID operationId,LocalDate start,LocalDate end){refreshes++;if(refreshFails)throw new IllegalStateException("source unavailable");return calendar();}
  public Boundary boundary(String instrument){boundaryReads++;if(instrument.equals(badStock))throw new IllegalStateException("stock unavailable");return new Boundary(instrument,raw,published,AlertScanPlan.expected(calendar(),f.clock.instant(),20),f.clock.instant());}
  public Page due(String stock,String after,int limit){if(pageFails)throw new IllegalStateException("second page unavailable");if(crossCutoff)f.clock.advance(14400);var selected=rules.stream().filter(r->stock==null||stock.equals(r.instrumentId())).filter(r->after==null||r.ruleId().toString().compareTo(after)>0).toList();return paginate&&selected.size()>1?new Page(List.of(selected.get(0)),selected.get(0).ruleId().toString()):new Page(selected,null);}
 }
}
